def normalize_phones(apps, schema_editor):
    """Store every number as 10 digits (so phone login finds it) and clear duplicates, which
    the new unique constraint would reject. Numbers that aren't Indian mobiles are kept as-is."""
    import re

    User = apps.get_model("accounts", "User")
    seen = set()
    for user in User.objects.exclude(phone="").order_by("date_joined", "pk"):
        digits = re.sub(r"\D", "", user.phone)
        if len(digits) == 12 and digits.startswith("91"):
            digits = digits[2:]
        elif len(digits) == 11 and digits.startswith("0"):
            digits = digits[1:]
        phone = digits if re.fullmatch(r"[6-9]\d{9}", digits) else user.phone
        if phone in seen:
            phone = ""
        seen.add(phone)
        if phone != user.phone:
            User.objects.filter(pk=user.pk).update(phone=phone)


